```sql
/* Находим город и должность с минимальной зарплатой */
SELECT "city", "job" FROM (
  SELECT "city", "job", ROW_NUMBER() OVER (ORDER BY "salary" ASC) AS rn
  FROM "jobs"
) t
WHERE rn = 1;
```

